mapper.select:
SELECT count(1), min(duar.source_id) min_id, max(duar.source_id) max_id
FROM dwd_user_ad_record duar
WHERE duar.dates = #{dates}

SELECT count(1), min(omasda.id) min_id, max(omasda.id) max_id
FROM ods_max_ad_stat_detail_ads omasda
WHERE omasda.dates = #{dates}

SELECT duar.id, omasda.id source_id, omasda.dates, dui.user_id, dui.last_version `version`, dui.pkg, dui.country, omasda.ad_format, omasda.network, omasda.ad_exhibit, omasda.revenue, omasda.created source_create_time FROM ods_max_ad_stat_detail_ads omasda LEFT JOIN dwd_user_ad_record duar on (duar.source_id = omasda.id and duar.dates = omasda.dates) INNER JOIN dim_user_info dui on (omasda.gaid = dui.gaid and omasda.pkg = dui.pkg) WHERE omasda.dates = #{dates}
and omasda.id > #{startSourceId}
LIMIT #{rowNum}
